    version, deleted, created_at, created_by, updated_at, updated_by
) VALUES (
    #{batchId}, #{studentId}, #{doctorId}, #{recordTime}, #{source},
    #{auditStatus}, #{abnormalFlag}, #{remark},
    0, 0, NOW(), #{createdBy}, NOW(), #{updatedBy}
)
